console.log("Привет, мир!"); // Выведет: Привет, мир!

// console.log() — это функция, которая отправляет текст в консоль браузера.
// Консоль — это «журнал» для разработчика, где можно видеть результат работы кода.

// Представьте, что в HTML есть элемент: <p id="greeting">Привет!</p>

document.getElementById("greeting").textContent = "Привет, студент!";
// Получаем элемент по его ID и меняем текст внутри тега <p>.

// HTML: <button id="myBtn">Нажми меня</button>

document.getElementById("myBtn").addEventListener("click", function() {
    console.log("Кнопка нажата!"); // Эта строка выполнится только при клике
});

let hour = new Date().getHours(); // Получаем текущий час (0-23)

if (hour < 12) {
    console.log("Доброе утро!"); // Если меньше 12 — утро
} else {
    console.log("Добрый день!"); // Иначе — день или вечер
}
